"""Public lesson briefs. All business records below are fictional learning data."""
CARDS = {}

BIKE = (
    'Продължаващ учебен проект: велосипедна работилница в български град. '
    'Това е измислен бизнес за упражнение, не клиент или пазарно проучване. '
    'Работилницата приема велосипеди на действителен обект в условията на казуса. '
    'Не са предоставени реален адрес, график, свободни часове или окончателна цена. '
    'Не създавай публичен профил за този пример. „Изпрати запитване“ не означава „запазен час“.'
)
REQUESTS = (
    'Дадени са 12 измислени записа. Въпросът е основният въпрос в записа, не диагноза за мотива.\n'
    'В01: „Има ли час утре? Колелото ми трябва за работа.“\n'
    'В02: „Може ли да го донеса в събота?“\n'
    'В03: „Приемате ли днес след 17 часа?“\n'
    'В04: „Има ли свободен час тази седмица?“\n'
    'В05: „Работите ли в неделя?“\n'
    'В06: „Как се определя цената за смяна на верига?“\n'
    'В07: „Какво влиза в цената за преглед?“\n'
    'В08: „Плаща ли се отделно за частите?“\n'
    'В09: „Получавам ли цена преди ремонта?“\n'
    'В10: „Колко време ще остане при вас?“\n'
    'В11: „Ще е готово ли преди пътуването в петък?“\n'
    'В12: повторно изпращане на В02, същият учебен идентификатор.\n'
    'Има 5 първи записа за час, 4 за цена, 2 за срок и 1 дубликат: 11 уникални запитвания. '
    'Този пакет не измерва пазара. Допълнителните числа в отделен урок са отделен учебен случай.'
)
MODE = (
    'Начален маршрут: работи по предоставените данни на лист или в безплатен текстов редактор. '
    'Не са нужни собствен бизнес, платен AI, рекламен бюджет или външен акаунт. '
    'Реалната настройка е отделна практика при допустим достъп и разрешение. '
    'Пази работата при себе си; завършването на урока не изисква свободен отговор или преподавател. '
    'Тестовете проверяват решения по учебни случаи; не удостоверяват публикуван проект или истински продажби.'
)

def card(lid, opening, skills, terms, bridge, facts, task, checks, sample, hints, table=None, sources=()):
    assert len(skills) == len(checks) == 3 and len(hints) == 2
    CARDS[lid] = dict(opening=opening, skills=skills, terms=terms, bridge=bridge,
                      facts=facts, task=task, checks=checks, sample=sample, hints=hints,
                      table=table, sources=sources)

